/// Match the whole of text against the glob pattern. Characters are
/// Unicode scalar values (chars) and matching is case-sensitive. Pattern syntax:
///   ?       matches exactly one character.
///   *       matches any sequence of characters, including the empty one.
///   [set]   matches exactly one character that is in the set; [!set]
///           matches exactly one character that is not in the set. In a set,
///           x-y is an inclusive range of code points; a ] that comes first
///           (right after [ or [!) is a literal member; a - that comes first
///           or last is a literal member; ^ and \ have no special meaning.
///   \c      (backslash then any character c) matches c literally.
///   any other character matches itself.
/// The pattern is invalid if a [ has no closing ], if it ends in a lone
/// backslash, or if a range has its start after its end (as in [z-a]); for an
/// invalid pattern return None, whatever the text. Otherwise return Some(true)
/// or Some(false). Patterns and texts may be hundreds of characters long with
/// many stars, so the running time must be polynomial (no exponential
/// backtracking).
/// >>> wildcard_match("*.py", "main.py")
/// Some(true)
/// >>> wildcard_match("a[b", "ab")
/// None
fn wildcard_match(pattern: &str, text: &str) -> Option<bool> {
    let tokens = parse_glob(pattern)?;
    let t: Vec<char> = text.chars().collect();
    let (mut p, mut i) = (0usize, 0usize);
    let mut star: Option<usize> = None;
    let mut star_i = 0usize;
    while i < t.len() {
        if p < tokens.len() && tokens[p] != Tok::Star && tok_matches(&tokens[p], t[i]) {
            p += 1;
            i += 1;
        } else if p < tokens.len() && tokens[p] == Tok::Star {
            star = Some(p);
            star_i = i;
            p += 1;
        } else if let Some(s) = star {
            // let the last star absorb one more character and retry
            star_i += 1;
            p = s + 1;
            i = star_i;
        } else {
            return Some(false);
        }
    }
    while p < tokens.len() && tokens[p] == Tok::Star {
        p += 1;
    }
    Some(p == tokens.len())
}

#[derive(PartialEq)]
enum Tok {
    Star,
    Any,
    Lit(char),
    Set(bool, Vec<(char, char)>),
}

fn tok_matches(tok: &Tok, c: char) -> bool {
    match tok {
        Tok::Star | Tok::Any => true,
        Tok::Lit(x) => *x == c,
        Tok::Set(neg, items) => items.iter().any(|&(lo, hi)| lo <= c && c <= hi) != *neg,
    }
}

fn parse_glob(pattern: &str) -> Option<Vec<Tok>> {
    let p: Vec<char> = pattern.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < p.len() {
        match p[i] {
            '*' => { out.push(Tok::Star); i += 1; }
            '?' => { out.push(Tok::Any); i += 1; }
            '\\' => {
                if i + 1 >= p.len() { return None; }
                out.push(Tok::Lit(p[i + 1]));
                i += 2;
            }
            '[' => {
                let mut j = i + 1;
                let neg = j < p.len() && p[j] == '!';
                if neg { j += 1; }
                let mut items = Vec::new();
                let mut first = true;
                loop {
                    if j >= p.len() { return None; }
                    if p[j] == ']' && !first { break; }
                    first = false;
                    if j + 2 < p.len() && p[j + 1] == '-' && p[j + 2] != ']' {
                        if p[j] > p[j + 2] { return None; }
                        items.push((p[j], p[j + 2]));
                        j += 3;
                    } else {
                        items.push((p[j], p[j]));
                        j += 1;
                    }
                }
                out.push(Tok::Set(neg, items));
                i = j + 1;
            }
            c => { out.push(Tok::Lit(c)); i += 1; }
        }
    }
    Some(out)
}
